class Middleware:
    def __init__(self, cls: type, **options: typing.Any) -> None:
        self.cls = cls
        self.options = options

    def __iter__(self) -> typing.Iterator:
        as_tuple = (self.cls, self.options)
        return iter(as_tuple)

    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        option_strings = [f"{key}={value!r}" for key, value in self.options.items()]
        args_repr = ", ".join([self.cls.__name__] + option_strings)
        return f"{class_name}({args_repr})"

@debug.setter
def debug(self, value: bool) -> None:
    self._debug = value
    self.middleware_stack = self.build_middleware_stack()

def url_path_for(self, name: str, **path_params: typing.Any) -> URLPath:
    return self.router.url_path_for(name, **path_params)

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    scope["app"] = self
    await self.middleware_stack(scope, receive, send)

def on_event(self, event_type: str) -> typing.Callable:  # pragma: nocover
    return self.router.on_event(event_type)

def mount(
    self, path: str, app: ASGIApp, name: typing.Optional[str] = None
) -> None:  # pragma: nocover
    self.router.mount(path, app=app, name=name)

def host(
    self, host: str, app: ASGIApp, name: typing.Optional[str] = None
) -> None:  # pragma: no cover
    self.router.host(host, app=app, name=name)

def add_middleware(
    self, middleware_class: type, **options: typing.Any
) -> None:  # pragma: no cover
    self.user_middleware.insert(0, Middleware(middleware_class, **options))
    self.middleware_stack = self.build_middleware_stack()

def add_exception_handler(
    self,
    exc_class_or_status_code: typing.Union[int, typing.Type[Exception]],
    handler: typing.Callable,
) -> None:  # pragma: no cover
    self.exception_handlers[exc_class_or_status_code] = handler
    self.middleware_stack = self.build_middleware_stack()

def add_event_handler(
    self, event_type: str, func: typing.Callable
) -> None:  # pragma: no cover
    self.router.add_event_handler(event_type, func)

def add_route(
    self,
    path: str,
    route: typing.Callable,
    methods: typing.Optional[typing.List[str]] = None,
    name: typing.Optional[str] = None,
    include_in_schema: bool = True,
) -> None:  # pragma: no cover
    self.router.add_route(
        path, route, methods=methods, name=name, include_in_schema=include_in_schema
    )

def add_websocket_route(
    self, path: str, route: typing.Callable, name: typing.Optional[str] = None
) -> None:  # pragma: no cover
    self.router.add_websocket_route(path, route, name=name)

def exception_handler(
    self, exc_class_or_status_code: typing.Union[int, typing.Type[Exception]]
) -> typing.Callable:
    warnings.warn(
        "The `exception_handler` decorator is deprecated, and will be removed in version 1.0.0. "  # noqa: E501
        "Refer to https://www.starlette.io/exceptions/ for the recommended approach.",  # noqa: E501
        DeprecationWarning,
    )

    def decorator(func: typing.Callable) -> typing.Callable:
        self.add_exception_handler(exc_class_or_status_code, func)
        return func

    return decorator

def route(
    self,
    path: str,
    methods: typing.Optional[typing.List[str]] = None,
    name: typing.Optional[str] = None,
    include_in_schema: bool = True,
) -> typing.Callable:
    """
    We no longer document this decorator style API, and its usage is discouraged.
    Instead you should use the following approach:

    >>> routes = [Route(path, endpoint=...), ...]
    >>> app = Starlette(routes=routes)
    """
    warnings.warn(
        "The `route` decorator is deprecated, and will be removed in version 1.0.0. "  # noqa: E501
        "Refer to https://www.starlette.io/routing/ for the recommended approach.",  # noqa: E501
        DeprecationWarning,
    )

    def decorator(func: typing.Callable) -> typing.Callable:
        self.router.add_route(
            path,
            func,
            methods=methods,
            name=name,
            include_in_schema=include_in_schema,
        )
        return func

    return decorator

def websocket_route(
    self, path: str, name: typing.Optional[str] = None
) -> typing.Callable:
    """
    We no longer document this decorator style API, and its usage is discouraged.
    Instead you should use the following approach:

    >>> routes = [WebSocketRoute(path, endpoint=...), ...]
    >>> app = Starlette(routes=routes)
    """
    warnings.warn(
        "The `websocket_route` decorator is deprecated, and will be removed in version 1.0.0. "  # noqa: E501

@pytest.mark.parametrize(
    "middleware_cls",
    [
        CustomMiddlewareWithoutBaseHTTPMiddleware,
        pytest.param(
            CustomMiddlewareUsingBaseHTTPMiddleware,
            marks=pytest.mark.xfail(
                reason=(
                    "BaseHTTPMiddleware creates a TaskGroup which copies the context"
                    "and erases any changes to it made within the TaskGroup"
                ),
                raises=AssertionError,
            ),
        ),
    ],
)
def test_contextvars(test_client_factory, middleware_cls: type):
    # this has to be an async endpoint because Starlette calls run_in_threadpool
    # on sync endpoints which has it's own set of peculiarities w.r.t propagating
    # contextvars (it propagates them forwards but not backwards)
    async def homepage(request):
        assert ctxvar.get() == "set by middleware"
        ctxvar.set("set by endpoint")
        return PlainTextResponse("Homepage")

    app = Starlette(
        middleware=[Middleware(middleware_cls)], routes=[Route("/", homepage)]
    )

    client = test_client_factory(app)
    response = client.get("/")
    assert response.status_code == 200, response.content
